void SMulU64Sop2::execute_impl(amdgpu::Wavefront &wf) {
  uint64_t s0 = ssrc0.read_scalar64(wf);
  uint64_t s1 = ssrc1.read_scalar64(wf);
  sdst.write_scalar64(wf, static_cast<uint64_t>(s0 * s1));
}

